class NomBanco extends BaseNomBanco
{

    public function setUp()
    {
        $this->hasMany('NomSucursal', array('local' => 'idbanco', 'foreign' => 'idbanco'));
        /*$this->hasMany('NomCuentaBancaria', array('local' => 'idbanco', 'foreign' => 'idbanco'));*/
        parent::setUp();
    }

    /**
     * Obtiene los bancos de acuerdo con los criterios de búsqueda
     *
     * @param array $cond Arreglo de Condiciones
     * @param int   $limit Límite superior
     * @param int   $start Comienzo inferior
     *
     * @return array
     * @throws Doctrine_Exception|Exception
     */
    public function buscarBanco($cond = array(), $limit = null, $start = null)
    {
        try {
            $filter = self::aplicarFiltro($cond);
            $q = new Doctrine_Query();
            $q->from('NomBanco e')->where($filter);

            if(!is_null($limit) && !is_null($start)){
                $q->limit($limit)->offset($start);
            }
            $resultado = $q->execute()->toArray();
            if ($cond['sfFiltro'] != '') {
                include_once Zend_Registry::get('config')->dir_aplication .
                    'configuracion/comun/models/bussines/UtilesDatosMaestros.php';
                $resultado = UtilesDatosMaestros::colorSearch($resultado,
                    array('nombre', 'codigo', 'abreviatura'),
                    array($cond['sfFiltro'], $cond['sfFiltro'], $cond['sfFiltro']));
            }
            $cantidad = self::Cantidad($filter);
            return array('cant' => $cantidad, 'datos' => $resultado);
        } catch (Doctrine_Exception $ee) {
            throw $ee;
        }
    }

    /**
     * Obtiene todos los bancos
     *
     * @author Ing. Lisvany Alonso Martinez
     *
     * @throws Doctrine_Exception
     * @throws Exception
     */
    public function ObtenerBancos()
    {
        try {
            $q = new Doctrine_Query();
            $bancos = $q->from('NomBanco e')->execute();
            $arraybancos = $bancos->toArray();

            return $arraybancos;
        } catch (Doctrine_Exception $ee) {
            throw $ee;
        }
    }

    /**
     * Transforma las condiciones en claúsulas where de sql
     *
     * @param array $cond Arreglo de condiciones
     *
     * @return string
     */
    public function aplicarFiltro($cond)
    {
        $codigo = $cond['codigo'];
        $nombre = $cond['nombre'];
        $filter = " 0 = 0 ";

        if ($cond['codigo'] != '' && $cond['nombre'] != '') {
            $filter .= " and lower(e.codigo) ilike '%" . $codigo . "%'
                and lower(e.nombre) ilike '%" . $nombre . "%'";
            return $filter;
        } elseif ($cond['idbanco'] != '') {
            $filter .= " and e.idbanco = '" . $cond['idbanco'] . "'";
            return $filter;
        } elseif ($cond['codigo'] != '') {
            $filter .= " and lower(e.codigo) ilike '%" . $codigo . "%'";
            return $filter;
        } elseif ($cond['nombre'] != '') {
            $filter .= " and lower(e.nombre) ilike '%" . $nombre . "%'";
            return $filter;
        } elseif ($cond['sfFiltro'] != '') {
            $filter .= " and (e.nombre ilike '%" . $cond['sfFiltro'] . "%' OR e.codigo ilike '%" . $cond['sfFiltro']
                . "%' OR e.abreviatura ilike '%" . $cond['sfFiltro'] . "%')";
            return $filter;
        }
        return $filter;
    }

    /**
     * Obtiene los bancos que contengan sucursal(es)
     *
     * @return array
     */
    public function buscarBancoConSucursal( /* $cond = array(), $limit = 10, $start = 0 */)
    {
        $q = Doctrine_Query::create();
        $result = $q->from('NomBanco b')->innerJoin('b.NomSucursal')->execute()->toArray(true);
        $cantidad = self::Cantidad();
        $resultado = array('cant' => $cantidad, 'datos' => $result);
        return $resultado;
    }

    /**
     * Verifica que el banco contenga sucursal(es)
     *
     * @param int $idbanco Identificador de Banco
     *
     * @return bool
     */
    public function verificarBancoConSucursal($idbanco)
    {
        $q = Doctrine_Query::create();
        $result = $q->from('NomBanco b')->innerJoin('b.NomSucursal')->where('b.idbanco=?', $idbanco)->execute()
            ->toArray();
        return (count($result) > 0) ? true : false;
    }

    /**
     * Obtiene la cantidad de bancos existentes dado un filtro
     *
     * @param string $filter claúsulas where en sql
     *
     * @return mixed
     */
    public function Cantidad($filter = null)
    {
        $q = new Doctrine_Query();
        if ($filter) {
            $count = $q->select("COUNT(e.idbanco) cant ")->from("NomBanco e")->where($filter)->execute();
        } else {
            $count = $q->select("COUNT(e.idbanco) cant ")->from("NomBanco e")->execute();
        }

        $cant = $count->toArray();
        return $cant[0]['cant'];
    }

    /**
     * Verifica la existencia de un banco
     *
     * @param string $codigo Código banco
     * @param string $nombre Nombre banco
     *
     * @return bool
     */
    public function verificarExisteBanco($codigo = '', $nombre = '')
    {
        $query = new Doctrine_Query();
        $result = $query->select("COUNT(e.idbanco) cant ")
            ->from("NomBanco e")
            ->where("lower(e.nombre) = lower(?) OR e.codigo = ?", array($nombre, $codigo))
            ->execute();
        $cantidad = $result->toArray();
        if ($cantidad[0]['cant'] > 0) {
            return true;
        } else {
            return false;
        }
    }

    /**
     * Verifica que la abreviatura del banco a insertar no exista
     *
     * @param String $abreviatura Abreviatura de banco
     *
     * @return bool Si encuantra alguna coincidencia retorna true
     * @author Ing. Lisvany Alonso Martinez
     */
    public function verificarAbreviatura($abreviatura = '')
    {
        $query = new Doctrine_Query();
        $result = $query->select("COUNT(e.idbanco) cant ")
            ->from("NomBanco e")
            ->where("lower(e.abreviatura) = lower(?)", array($abreviatura))
            ->execute();
        $cantidad = $result->toArray();
        if ($cantidad[0]['cant'] > 0) {
            return true;
        } else {
            return false;
        }
    }

    /**
     * Verifica que la abreviatura o el nombre del banco a insertar no no coincidan entre ellas
     *
     * @author Ing. Lisvany Alonso Martinez
     *
     * @param String $abreviatura Abreviatura del banco
     * @param String $nombre      Nombre del banco
     *
     * @return bool Si encuantra alguna coincidencia retorna true
     */
    public function verificarAbreviaturaVsBanco($abreviatura = '', $nombre = '')
    {
        $query = new Doctrine_Query();
        $result = $query->select("COUNT(e.idbanco) cant ")
            ->from("NomBanco e")
            ->where("lower(e.nombre) = lower(?) OR lower(e.abreviatura) = lower(?)", array($abreviatura, $nombre))
            ->execute();
        $cantidad = $result->toArray();
        if ($cantidad[0]['cant'] > 0) {
            return true;
        } else {
            return false;
        }
    }

    /**
     * convierte a minuscula y quita tildes
     *
     * @param string $text
     *
     * @return string
     */
    public function replaceLower($text)
    {
        $text = utf8_decode($text);
        $text = ereg_replace(("�|�"), ("a"), $text);
        $text = ereg_replace(("�|�"), ("e"), $text);
        $text = ereg_replace(("�|�"), ("i"), $text);
        $text = ereg_replace(("�|�"), ("o"), $text);
        $text = ereg_replace(("�|�"), ("u"), $text);
        return strtolower($text);
    }

}
